#include <iostream>
#include <cmath>
using namespace std;

bool isSquare(long long n) {
    if (n < 0) return false;
    if (n == 0 || n == 1) return true;
    long long r = (long long)round(sqrt((double)n));
    while ((r + 1) <= 1000000000LL && (r + 1) * (r + 1) <= n) r++;
    while (r * r > n) r--;
    return r * r == n;
}

int main() {
    long long n;
    if (cin >> n) {
        cout << (isSquare(n) ? "YES" : "NO") << "\n";
    }
    return 0;
}

#include <iostream>
using namespace std;

int gcd(int x, int y) {
    while (y != 0) {
        int r = x % y;
        x = y;
        y = r;
    }
    return x;
}

void reduce(int &a, int &b) {
    int g = gcd(a, b);
    a /= g;
    b /= g;
}

int main() {
    int a, b;
    if (cin >> a >> b) {
        reduce(a, b);
        cout << a << " " << b << "\n";
    }
    return 0;
}

