#include <iostream>
using namespace std;

long long calcStore(long long v) {
    long long base = 0;
    if (v <= 10) base = v * 10000;
    else if (v <= 20) base = 10 * 10000 + (v - 10) * 15000;
    else base = 10 * 10000 + 10 * 15000 + (v - 20) * 20000;
    long long withVat = base + base / 10;
    if (withVat >= 500000) withVat -= 50000;
    return withVat;
}

int main() {
    int n;
    if (cin >> n) {
        long long total = 0;
        for (int i = 0; i < n; i++) {
            long long v; cin >> v;
            total += calcStore(v);
        }
        cout << total << "\n";
    }
    return 0;
}

#include <iostream>
#include <vector>
using namespace std;

int main() {
    int r, c;
    if (cin >> r >> c) {
        vector<vector<long long>> a(r, vector<long long>(c));
        for (int i = 0; i < r; i++)
            for (int j = 0; j < c; j++)
                cin >> a[i][j];
        vector<long long> v;
        v.reserve(r * c);
        for (int i = 0; i < r; i++) {
            if (i % 2 == 0) {
                for (int j = 0; j < c; j++) v.push_back(a[i][j]);
            } else {
                for (int j = c - 1; j >= 0; j--) v.push_back(a[i][j]);
            }
        }
        int cnt = 0;
        for (size_t i = 1; i + 1 < v.size(); i++) {
            if (v[i] > v[i - 1] && v[i] > v[i + 1]) cnt++;
        }
        cout << cnt << "\n";
    }
    return 0;
}

